Lemma lin_testB_mono : forall bc c d ts (T1 T2 : Z -> Z -> bool),
  (forall x y, T1 x y = true -> T2 (x + d) (y + d) = true) ->
  lin_testB bc c ts T1 = true -> lin_testB bc (c + d) ts T2 = true.
Proof.
