Lemma entriesGF_eq : forall bc X sxs info bnds kn infos, XOK bc X ->
  entriesGF bc X (map (mk_sxi X) sxs) (mk_glF bc info X bnds (map (mk_sxi X) sxs)) kn infos = entriesG bc sxs (mk_gl bnds sxs) kn infos.
