Fixpoint nth4 {A : Type} (n : nat) (l : list A) (d : A) {struct n} : A :=
  match n with
  | S (S (S (S m))) => match l with _ :: _ :: _ :: _ :: r => nth4 m r d | _ => nth n l d end
  | _ => nth n l d
