Fixpoint in_sides_num (bc : bctx) (D : list (saddr * expr)) (b : expr) (k n : Z) : bool :=
  match D with
  | [] => false
  | (c, m) :: r => if num_sub bc b k n c m then true else in_sides_num bc r b k n
  end.
