Definition EINFF (bc : bctx) (t : ntab) (K : kentry) (oi : option einfoF) : Prop :=
  match oi with
  | None => kdescr K = None
  | Some e => EINF bc t K (Some (ef_ei e)) /\ (forall m, ef_m e = Some m -> ef_end e = ef_k e + m)
  end.
