Lemma scanF_sim : forall bc kn t gs gs' infos1 t1 gs1 infos2 t2 gs2,
  scanF bc kn t gs = (infos1, t1, gs1) -> scan_entries bc kn t gs' = (infos2, t2, gs2) ->
  t1 = t2 /\ map ei_strip (map (option_map ef_ei) infos1) = map ei_strip infos2.
Proof.
