Fixpoint forallbF {T : Type} (f : T -> bool) (l : list T) : bool :=
  match l with [] => true | x :: r => if f x then forallbF f r else false end.
Lemma forallbF_in : forall T (f : T -> bool) l, forallbF f l = true -> forall x, In x l -> f x = true.
Proof.
