Definition GMEMO (bc : bctx) (glo ghi : Z) (gx : option gxi) (m : smemo) : Prop :=
  match gx with Some x => MEMO_OK bc (gx_b x) glo (ghi - glo) m | None => True end.
Lemma linV2M_ok : forall bc si b glo ghi gx m, GMEMO bc glo ghi gx m ->
