           then match sb_find R' b with
                | Some se => chainKI bc (si_bx si) (sbe_fl se) a e (KWord (sx_a sx) (sx_w sx) (sx_v sx))
                                     (Some (a_base (sx_a sx))) (Pos.eqb b) (sx_br sx)
                | None => gen tt
                end
           else gen tt
       | _, _ => gen tt
       end)
  end.

