Definition olf (o : option Z) (f : Z -> bool) (c : Z) : bool := match o with Some l => f (l + c) | None => false end.
Lemma lin_testB_lof : forall bc c ts (f : Z -> bool), (forall x y, x <= y -> f x = true -> f y = true) ->
  lin_testB bc c ts (fun lo _ => f lo) = olf (lin_lo bc ts) f c.
Proof.
