(* [comment removed for export] *)
Record gp := GP { gp_l1 : option Z; gp_a1 : Z; gp_c2 : Z; gp_l2 : option Z; gp_a2 : Z; gp_3 : option (Z * option Z * Z); gp_s : option (Z * Z) }.
Definition mk_gp (bc : bctx) (ts : list (Z * expr)) : gp :=
  let '(c2, t2) := srl_expandB bc ts in
  let j := srl_scale_need ts in
  GP (lin_lo bc ts) (lin_align (ealignB bc) ts) c2 (lin_lo bc t2) (lin_align (ealignB bc) t2)
     (if has_srl t2 then let '(c3, t3) := srl_expandB bc t2 in Some (c3, lin_lo bc t3, lin_align (ealignB bc) t3) else None)
     (if (if Z.ltb 0 j then Z.leb j 24 else false) then
        let sc := 2 ^ j in
        let ts' := List.map (fun t => (sc * fst t, snd t)) ts in
        let '(c2', t2') := srl_expandB bc ts' in
        let '(c3', t3') := (if has_srl t2' then srl_expandB bc t2' else (0, t2')) in
        match lin_lo bc t3' with Some l => Some (sc, l + c2' + c3') | None => None end
      else None).
Definition ge0P (g : gp) (C : Z) : bool :=
  let s1 := 2 ^ (Z.min (ctzq C) (gp_a1 g)) in
  if olf (gp_l1 g) (slackf s1) C then true
  else if olf (gp_l2 g) (slackf2 s1 (2 ^ (Z.min (ctzq (C + gp_c2 g)) (gp_a2 g)))) (C + gp_c2 g) then true
  else if (match gp_3 g with
           | Some (c3, l3, a3) => olf l3 (slackf2 s1 (2 ^ (Z.min (ctzq (C + gp_c2 g + c3)) a3))) (C + gp_c2 g + c3)
           | None => false
           end) then true
  else match gp_s g with Some (sc, l) => Z.leb 0 (l + sc * C) | None => false end.
Lemma lin_ge0_scaledB_gp : forall bc C ts, lin_ge0_scaledB bc C ts = match gp_s (mk_gp bc ts) with Some (sc, l) => Z.leb 0 (l + sc * C) | None => false end.
Proof.
